private val parsed = HashMap<String, Path>()

private fun pathFor(name: String): Path? = parsed.getOrPut(name) {
    val d = ICON_PATHS[name] ?: return null
    PathParser().parsePathString(d).toPath().apply { if (name == "shield-home") fillType = androidx.compose.ui.graphics.PathFillType.EvenOdd }
}

/** A Material Design icon by name without the "mdi:" (for example "shield-home"). Draws nothing for a name it doesn't have. */
@Composable
fun WIcon(name: String, tint: Color, size: Dp, modifier: Modifier = Modifier) {
    val path = pathFor(name)
    Canvas(modifier.size(size)) {
        if (path != null) {
            val s = this.size.minDimension / 24f
            withTransform({ scale(s, s, pivot = Offset.Zero) }) { drawPath(path, tint) }
        }
    }
}

/** Whether the watch has this icon (the tests check every name the screens use). */
fun hasWatchIcon(name: String) = name in ICON_PATHS
